public sealed class CleanerSettings {
 public string UpdateUrl="",RecoveryDirectory="",Language="zh-CN",Theme="dark",GlassMode="internal";public bool ScanCacheEnabled=true;public bool LiquidGlass=true;public bool AutomaticUpdates,UseWinapp2=true;public bool? EnableWinapp2,EnableJson,AutomaticWinapp2,AutomaticJson;public bool AutoWinapp2{get{return AutomaticWinapp2??(AutomaticUpdates&&UseWinapp2);}}public bool AutoJson{get{return AutomaticJson??(AutomaticUpdates&&!UseWinapp2);}}public bool Winapp2Enabled{get{return EnableWinapp2??true;}}public bool JsonEnabled{get{return EnableJson??!UseWinapp2;}}public string LastUpdateAttempt="",LastWinapp2Attempt="";public List<string> PortableDirectories=new List<string>();
 public static string Root{get{return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"ClearSpace");}}
 public static CleanerSettings Load(){try{var s=new JavaScriptSerializer().Deserialize<CleanerSettings>(File.ReadAllText(Path.Combine(Root,"settings.json")))??new CleanerSettings();s.Language=UiText.Normalize(s.Language);s.Theme=UiTheme.Normalize(s.Theme);s.GlassMode=UiGlass.NormalizeMode(s.GlassMode);s.UpdateUrl=RuleSourceAddresses.Json(s.UpdateUrl);s.RecoveryDirectory=s.RecoveryDirectory??"";s.LastUpdateAttempt=s.LastUpdateAttempt??"";s.PortableDirectories=(s.PortableDirectories??new List<string>()).Where(p=>!String.IsNullOrWhiteSpace(p)&&Regex.IsMatch(p,"^[a-zA-Z]:\\\\")).Distinct(StringComparer.OrdinalIgnoreCase).Take(30).ToList();if(s.RecoveryDirectory.Length>0&&!Regex.IsMatch(s.RecoveryDirectory,"^[a-zA-Z]:\\\\"))s.RecoveryDirectory="";s.RecoveryDirectory=BackupFolders.UpgradeDefault(s.RecoveryDirectory);return s;}catch{return new CleanerSettings();}}
 public void Save(){AtomicFile.Write(Path.Combine(Root,"settings.json"),new JavaScriptSerializer().Serialize(this));}
}
public static class AtomicFile {
 public static void Write(string path,string text){string directory=Path.GetDirectoryName(Path.GetFullPath(path));Directory.CreateDirectory(directory);if(!Engine.SafeAncestors(Path.Combine(directory,"probe")))throw new IOException("保存目录包含链接或无法验证");string tmp=Path.Combine(directory,Guid.NewGuid().ToString("N")+".tmp");try{using(var stream=new FileStream(tmp,FileMode.CreateNew,FileAccess.Write,FileShare.None)){byte[] data=Encoding.UTF8.GetBytes(text);stream.Write(data,0,data.Length);stream.Flush(true);}if(File.Exists(path)){if((File.GetAttributes(path)&FileAttributes.ReparsePoint)!=0)throw new IOException("拒绝覆盖链接文件");File.Replace(tmp,path,null);}else File.Move(tmp,path);}finally{if(File.Exists(tmp))File.Delete(tmp);}}
}
